<?php
declare(strict_types=1); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/csrf.php'; require_once __DIR__ . '/../config/database.php'; require_csrf();
$first = post_string('first_name',50); $middle = post_string('middle_name',50); $last = post_string('last_name',50); $designation = post_string('designation',50); $department = post_string('department',25); $username = post_string('username',25); $password = (string)($_POST['password'] ?? ''); $confirm = (string)($_POST['password_confirmation'] ?? '');
if (!$first || !$middle || !$last || !$designation || !$department || strlen($username) < 4 || strlen($password) < 8 || $password !== $confirm) { flash('error','Complete all fields, use an 8+ character password, and ensure passwords match.'); redirect('auth/register.php'); }
$check=$conn->prepare('SELECT id FROM dr_users WHERE username = ? LIMIT 1'); $check->bind_param('s',$username); $check->execute(); if(fetch_one($check)){flash('error','That username is already in use.');redirect('auth/register.php');}
$first=ucwords(strtolower($first));$middle=ucwords(strtolower($middle));$last=ucwords(strtolower($last));$designation=ucwords(strtolower($designation));$hash=password_hash($password,PASSWORD_DEFAULT);$status='For Approval';$now=date('Y-m-d H:i:s');
$legacyName = '';
$stmt=$conn->prepare('INSERT INTO dr_users (name,fname,mname,lname,designation,department,username,password,status,datecreated) VALUES (?,?,?,?,?,?,?,?,?,?)');$stmt->bind_param('ssssssssss',$legacyName,$first,$middle,$last,$designation,$department,$username,$hash,$status,$now); if(!$stmt->execute()){flash('error','Unable to register the account.');redirect('auth/register.php');} flash('success','Registration submitted. Please wait for account approval.'); redirect('index.php');
